// Original imagegen texture: aged New England brick, flat seamless diffuse, soft console-game detail.
// 256px JPEG, 22928 bytes; embedded to keep this chapter self-contained.
import * as THREE from 'three';
const BRICK='data:image/jpeg;base64,';
export function dartmouthBrick(){
  const canvas=document.createElement('canvas');canvas.width=canvas.height=256;
  const g=canvas.getContext('2d');g.fillStyle='#754d43';g.fillRect(0,0,256,256);
  const t=new THREE.CanvasTexture(canvas),copies=[t];
  t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;
  t.clone=()=>{const copy=new THREE.Texture().copy(t);copies.push(copy);return copy;};
  const image=new Image();image.onload=()=>{g.drawImage(image,0,0,256,256);for(const copy of copies)copy.needsUpdate=true;};image.src=BRICK;
  return t;
}

const brickFacade="data:image/jpeg;base64,";

const whiteFacade="data:image/jpeg;base64,";

const snowSurface="data:image/jpeg;base64,";

const shopFacade="data:image/jpeg;base64,";

// Original imagegen atlas: photographic sash facades, snowy ground and shopfront.
export function dartmouthSurface(kind, emissive=false){
 const sources={brickFacade,whiteFacade,snowSurface,shopFacade};
 const c=document.createElement('canvas');c.width=c.height=512;const g=c.getContext('2d');
 g.fillStyle=emissive?'#000':kind==='snowSurface'?'#cbd3df':'#827267';g.fillRect(0,0,512,512);
 const t=new THREE.CanvasTexture(c),copies=[t];t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;
 t.clone=()=>{const cp=new THREE.Texture().copy(t);copies.push(cp);return cp;};
 const im=new Image();im.onload=()=>{g.drawImage(im,0,0,512,512);if(emissive){const d=g.getImageData(0,0,512,512);for(let i=0;i<d.data.length;i+=4){const r=d.data[i],b=d.data[i+2],v=d.data[i+1];const k=r>v*1.12&&v>b*1.24&&r>95?Math.min(1,(r-b)/100):0;d.data[i]*=k;d.data[i+1]*=k;d.data[i+2]*=k;}g.putImageData(d,0,0);}for(const cp of copies)cp.needsUpdate=true;};im.src=sources[kind];return t;
}

// Small original material studies: painted joinery, cut stone, oxidised copper,
// tar and salt. Periodic noise keeps all four edges continuous when tiled.
export function dartmouthDetail(kind) {
  const c=document.createElement('canvas'); c.width=c.height=128;
  const g=c.getContext('2d'), im=g.createImageData(128,128);
  const palettes={grain:[250,250,250],wood:[215,211,198],stone:[193,191,181],copper:[83,128,110],timber:[123,99,74],metal:[104,111,116],road:[120,102,85],door:[49,72,60]};
  const base=palettes[kind]||palettes.wood;
  for(let y=0;y<128;y++)for(let x=0;x<128;x++){
    const n=Math.sin(x*17.13+y*39.71)*43758.5453,grain=(n-Math.floor(n)-.5)*.12;
    const cloud=Math.sin(x*Math.PI/32)*Math.cos(y*Math.PI/64)*.055;
    let k=.91+grain+cloud*2.2;
    if(['wood','timber','door'].includes(kind)) {
      k+=.045*Math.sin(x*2.3+Math.sin(y*.15));
      if(x%32<2)k-=.23; if(x%32===3)k+=.13;
      k-=.24*Math.exp(-(((y-122)/14)**2));
      k-=.1*Math.sin(x*.19+Math.sin(y*.04))**8;
    }
    if(kind==='stone'){if(y%32<2||(x+(Math.floor(y/32)%2)*32)%64<1)k-=.16;}
    if(kind==='copper'){k+=.14*Math.sin(x*.21)*Math.sin(y*.13);if(x%32<2)k-=.25;}
    if(kind==='road')k+=grain*.8+.055*Math.sin(x*.24+Math.sin(y*.1))*Math.cos(y*.17);
    const i=(y*128+x)*4; for(let j=0;j<3;j++)im.data[i+j]=base[j]*k; im.data[i+3]=255;
  }
  g.putImageData(im,0,0);
  if(kind==='road'||kind==='paving'){
    let seed=83;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
    g.fillStyle=kind==='road'?'#403b37':'#6f7177';g.fillRect(0,0,128,128);
    const step=kind==='road'?16:32;
    for(let y=0;y<128;y+=step)for(let x=-step;x<128;x+=step*2){
      const u=x+(y/step%2)*step,v=rand(),base=kind==='road'?[76,51,32]:[146,133,116];
      g.fillStyle=`rgb(${base[0]+v*77},${base[1]+v*51},${base[2]+v*35})`;g.fillRect(u+1,y+1,step*2-2,step-2);
      g.fillStyle='rgba(230,212,182,.25)';g.fillRect(u+2,y+2,step*2-4,1);
      for(let j=0;j<45;j++){g.fillStyle=rand()<.5?'rgba(24,24,27,.27)':'rgba(228,218,203,.23)';g.fillRect(u+rand()*step*2,y+rand()*step,1+rand()*3,1+rand()*2);}
    }
  }
  if(kind==='road'){
    // Salted thin snow remains in mortar and ragged patches between tyre ruts.
    for(let y=0;y<128;y++)for(let x=0;x<128;x++){
      const n=Math.sin(x*.13+Math.sin(y*.17))*Math.cos(y*.12)+Math.sin(x*.47+y*.21)*.3;
      if(n>.05||y%16<2){g.fillStyle=`rgba(204,192,201,${y%16<2?.65:.28+n*.17})`;g.fillRect(x,y,1,1);}
    }
  }
  if(kind==='door'){
    for(const x of [13,69])for(const y of [16,67]){
      g.fillStyle='#1d302b';g.fillRect(x,y,45,44);g.strokeStyle='#718072';g.strokeRect(x+2,y+2,41,40);g.fillStyle='#354d40';g.fillRect(x+6,y+7,33,30);
    }
    g.fillStyle='#b3a173';g.fillRect(59,58,4,12);
  }
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;return t;
}

// Periodic snow grains, compressed boot scuffs and chisel courses. No photographed
// drifts in the flat floor: geometry supplies the silhouette, texture supplies scale.
export function dartmouthSnow(kind='fresh') {
  const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');
  const im=g.createImageData(256,256),ice=kind==='ice'||kind==='carved';
  for(let y=0;y<256;y++)for(let x=0;x<256;x++){
    const noise=Math.sin(x*127.1+y*311.7)*43758.5453;
    // Wrapped value noise at several scales; no directional wave or mirrored diamond.
    const value=(xx,yy)=>{const v=Math.sin(xx*127.1+yy*311.7+19.3)*43758.5453;return v-Math.floor(v);};
    const field=scale=>{const u=x/scale,v=y/scale,ix=Math.floor(u),iy=Math.floor(v),n=256/scale;
      const fx=(u-ix)**2*(3-2*(u-ix)),fy=(v-iy)**2*(3-2*(v-iy));
      return (value(ix%n,iy%n)*(1-fx)+value((ix+1)%n,iy%n)*fx)*(1-fy)+(value(ix%n,(iy+1)%n)*(1-fx)+value((ix+1)%n,(iy+1)%n)*fx)*fy-.5;};
    const n=field(32)*42+field(8)*42+field(4)*16+(noise-Math.floor(noise)-.5)*15;
    const base=ice?[133,161,177]:kind==='roof'?[225,230,239]:kind==='trodden'?[132,131,153]:[137,137,166];
    const i=(y*256+x)*4;for(let j=0;j<3;j++)im.data[i+j]=base[j]+n*(kind==='carved'?1.05:ice?.38:1);im.data[i+3]=255;
  }
  g.putImageData(im,0,0);
  if(!ice)for(let i=0;i<180;i++){const x=i*73%256,y=i*117%257;g.fillStyle=kind==='trodden'?'rgba(100,80,87,.24)':'rgba(119,95,106,.16)';g.beginPath();g.ellipse(x,y,2+i%7,1+i%3,i,0,7);g.fill();}
  if(kind==='trodden')for(let i=0;i<110;i++){
    const x=(i*83)%256,y=(i*71)%256;g.strokeStyle='rgba(85,75,91,.30)';g.lineWidth=1;g.beginPath();g.ellipse(x,y,2+i%3,5+i%4,.3*Math.sin(i),0,Math.PI*2);g.stroke();
  }
  if(kind==='carved'){
    // Sawn ice blocks laid in courses: every block its own depth of blue, frosted joints with a dark line under them,
    // and clouds of trapped air.
    for(let row=0;row<8;row++){
      const off=(row%2)*32;
      for(let col=0;col<4;col++){
        const x=(col*64+off)%256;
        g.fillStyle=['rgba(255,255,255,.12)','rgba(16,46,78,.17)','rgba(255,255,255,.05)','rgba(26,66,98,.10)'][(row*5+col*3)%4];
        g.fillRect(x,row*32,64,32);if(x+64>256)g.fillRect(x-256,row*32,64,32);
        g.fillStyle='rgba(236,250,255,.5)';g.fillRect(x,row*32,1.5,32);
        g.fillStyle='rgba(22,52,84,.22)';g.fillRect(x+1.5,row*32,1.5,32);
      }
      g.fillStyle='rgba(236,250,255,.55)';g.fillRect(0,row*32,256,1.5);
      g.fillStyle='rgba(22,52,84,.26)';g.fillRect(0,row*32+1.5,256,1.5);
    }
    for(let i=0;i<30;i++){
      const x=i*97%256,y=i*61%256,r=6+i%5*4,a=g.createRadialGradient(x,y,0,x,y,r);
      a.addColorStop(0,'rgba(240,252,255,.36)');a.addColorStop(1,'rgba(240,252,255,0)');g.fillStyle=a;g.fillRect(x-r,y-r,2*r,2*r);
    }
  }
  if(ice){
    for(let i=0;i<35;i++){const x=i*73%256,y=i*47%256;g.strokeStyle='rgba(248,255,255,.55)';g.lineWidth=1;g.beginPath();g.moveTo(x,y);g.lineTo(x+9,y-35);g.lineTo(x+7,y-52);g.stroke();}
    for(let i=0;i<80;i++){g.strokeStyle=kind==='carved'?'rgba(231,250,255,.3)':'rgba(68,113,143,.18)';g.beginPath();const x=i*47%256,y=i*83%256;g.moveTo(x,y);g.lineTo(x+4,y-7);g.stroke();}
  }
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;return t;
}

// Lit masonry and room studies for the close Baker facade, at architectural scale.
export function bakerSurface(kind, seed=0) {
 const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');
 if(kind==='brick') {
  g.fillStyle='#756451';g.fillRect(0,0,256,256);
  for(let y=0;y<256;y+=16)for(let x=-32;x<256;x+=64){
   const u=x+(y%32?32:0),v=(Math.sin(x*12.9898+y*78.233)*43758.5453)%1*.5+.5;
   g.fillStyle=`rgb(${153+v*25},${99+v*19},${63+v*13})`;g.fillRect(u+1,y+1,62,14);
   g.fillStyle='rgba(255,211,155,.24)';g.fillRect(u+1,y+1,62,1);
   g.fillStyle='rgba(55,30,18,.3)';g.fillRect(u+1,y+14,62,1);
  }
  for(let i=0;i<8000;i++){g.fillStyle=i%2?'rgba(42,24,12,.24)':'rgba(255,238,202,.2)';g.fillRect(i*71%256,i*137%257,1,1);}
  for(let i=0;i<65;i++){const x=i*73%256,y=i*113%256,r=5+i%21;const d=g.createRadialGradient(x,y,0,x,y,r);d.addColorStop(0,'rgba(36,29,22,.35)');d.addColorStop(1,'rgba(36,29,22,0)');g.fillStyle=d;g.fillRect(x-r,y-r,r*2,r*2);}
 } else {
  g.fillStyle=['#bd9458','#c9a36c','#886d50','#d2ab76','#b1a087'][seed%5];g.fillRect(0,0,256,256);
  g.fillStyle='#574439';g.fillRect(20,35,90,65);g.fillStyle='#9a8059';g.fillRect(27,42,76,51);
  g.fillStyle='#57412e';g.fillRect(30,185,196,12);g.fillRect(46,197,12,59);g.fillRect(202,197,12,59);
  for(let i=0;i<9;i++){g.fillStyle=['#664532','#6b6752','#966846'][i%3];g.fillRect(138+i*8,139-i%3*6,6,45+i%3*6);}
  g.fillStyle='#584c3c';g.fillRect(70,126,6,60);g.fillStyle='#ffe2a1';g.beginPath();g.moveTo(55,104);g.lineTo(92,104);g.lineTo(110,140);g.lineTo(39,140);g.closePath();g.fill();
  for(let x=0;x<256;x++)if(x<42+seed*3||x>215-seed*2){g.fillStyle=`rgba(234,216,176,${.5+.27*Math.sin(x*.45)**2})`;g.fillRect(x,0,1,256);}
 }
 const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;return t;
}
